<?php
declare(strict_types=1);require_once __DIR__.'/../includes/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$stmt=db()->prepare('SELECT author_id,title FROM recipes WHERE id=?');$stmt->execute([$id]);$r=$stmt->fetch();
 if($r){if(in_array($action,['approve','reject'],true)){$status=$action==='approve'?'approved':'rejected';db()->prepare('UPDATE recipes SET status=?,published_at=IF(?="approved",COALESCE(published_at,NOW()),published_at),updated_at=NOW() WHERE id=?')->execute([$status,$status,$id]);notify((int)$r['author_id'],'moderation','Your recipe “'.$r['title'].'” was '.$status.'.',url('recipe.php?id='.$id));audit('MODERATE_RECIPE',$id,$status);flash('success','Recipe status updated to '.$status.'.');}elseif($action==='toggle_sponsored'){db()->prepare('UPDATE recipes SET is_sponsored=1-is_sponsored WHERE id=?')->execute([$id]);audit('TOGGLE_SPONSORED',$id);flash('success','Sponsored label updated.');}elseif($action==='toggle_premium'){db()->prepare('UPDATE recipes SET is_premium=1-is_premium WHERE id=?')->execute([$id]);audit('TOGGLE_PREMIUM',$id);flash('success','Premium label updated.');}}
 redirect('admin/recipes.php'.(!empty($_GET['status'])?'?status='.urlencode($_GET['status']):''));
}
$status=$_GET['status']??'';$where=$status&&in_array($status,['pending','approved','rejected'],true)?'WHERE r.status=?':'';$sql='SELECT r.*,u.display_name FROM recipes r JOIN users u ON u.id=r.author_id '.$where.' ORDER BY FIELD(r.status,"pending","approved","rejected"),r.created_at DESC';$stmt=db()->prepare($sql);$stmt->execute($where?[$status]:[]);$items=$stmt->fetchAll();$pageTitle='Recipe moderation';require __DIR__.'/../includes/header.php';?>
<section class="admin-head"><div class="container"><span class="eyebrow light">Content management</span><h1>Recipe moderation</h1><nav class="admin-tabs"><a href="<?=e(url('admin/index.php'))?>">Overview</a><a class="active" href="<?=e(url('admin/recipes.php'))?>">Recipes</a><a href="<?=e(url('admin/comments.php'))?>">Comments</a><a href="<?=e(url('admin/users.php'))?>">Users</a><a href="<?=e(url('admin/settings.php'))?>">Settings</a><a href="<?=e(url('admin/audit.php'))?>">Audit log</a></nav></div></section>
<section class="section container"><div class="filter-chips"><a class="<?=!$status?'active':''?>" href="<?=e(url('admin/recipes.php'))?>">All</a><a class="<?=$status==='pending'?'active':''?>" href="<?=e(url('admin/recipes.php?status=pending'))?>">Pending</a><a class="<?=$status==='approved'?'active':''?>" href="<?=e(url('admin/recipes.php?status=approved'))?>">Approved</a><a class="<?=$status==='rejected'?'active':''?>" href="<?=e(url('admin/recipes.php?status=rejected'))?>">Rejected</a></div><div class="table-wrap"><table><thead><tr><th>Recipe</th><th>Creator</th><th>Status</th><th>Commercial</th><th>Submitted</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><a href="<?=e(url('recipe.php?id='.$r['id']))?>"><strong><?=e($r['title'])?></strong></a><small><?=e($r['cuisine'])?> · <?=e($r['category'])?></small></td><td><?=e($r['display_name'])?></td><td><span class="status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?= $r['is_sponsored']?'Sponsored ':'' ?><?= $r['is_premium']?'Premium':'' ?></td><td><?=e(date('j M Y',strtotime($r['created_at'])))?></td><td><div class="action-row"><a class="button button-ghost button-small" href="<?=e(url('recipe_form.php?id='.$r['id']))?>">Edit</a><?php if($r['status']!=='approved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-small button-success" name="action" value="approve">Approve</button></form><?php endif;?><?php if($r['status']!=='rejected'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-small button-danger" name="action" value="reject">Reject</button></form><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-small button-ghost" name="action" value="toggle_sponsored">Sponsor</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-small button-ghost" name="action" value="toggle_premium">Premium</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
